// Reserve space for potential song-info overlay to avoid overlapping the centered dot
double reservedTop = 0.0;
if (config.showSongInfo) {
  final typography = Theme.of(context).extension<AppTypography>()!;
  final h1 = typography.heroSize * config.textScale;
  final h2 = typography.heroSize * 0.5 * config.textScale; // approximate two-line layout multiplier
  final overlayHeight = h1 * 1.18 + 8 + h2 * 1.18; // line heights rough estimate
  reservedTop = 12.0 + overlayHeight; // top padding + overlay height
}
final availableHeight = (constraints.maxHeight - reservedTop).clamp(0.0, double.infinity);
final maxAllowed = min(constraints.maxWidth, availableHeight) / 2;

